L["Policy, capability or clock observation availability reason for a nil time."] = "Verfügbarkeitsgrund aus Richtlinie, Client-Unterstützung oder Uhrbeobachtung für eine nil-Zeit."
-- en: "Policy, capability or required-observation availability reason."
L["Policy, capability or required-observation availability reason."] = "Verfügbarkeitsgrund aus Richtlinie, Client-Unterstützung oder erforderlicher Beobachtung."
