L["Policy, query, capability or required row/subject availability reason for a nil record."] = "Verfügbarkeitsgrund aus Richtlinie, Abfrage, Client-Unterstützung oder erforderlicher Zeile/erforderlichem Subjekt für einen nil-Datensatz."
