L["Policy, query-validation or availability reason for a nil pet observation."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit für eine nil-Begleiterbeobachtung."
-- en: "Policy, query-validation or availability reason for a nil player flag."
L["Policy, query-validation or availability reason for a nil player flag."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit für ein nil-Spieler-Flag."
-- en: "Policy, query-validation or availability reason for a nil quantity."
L["Policy, query-validation or availability reason for a nil quantity."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit für eine nil-Menge."
-- en: "Policy, query-validation or availability reason for a nil resource observation."
L["Policy, query-validation or availability reason for a nil resource observation."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit für eine nil-Ressourcenbeobachtung."
-- en: "Policy, query-validation or availability reason for a nil threat observation."
L["Policy, query-validation or availability reason for a nil threat observation."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit für eine nil-Bedrohungsbeobachtung."
-- en: "Policy, query-validation or availability reason for a nil unit flag."
L["Policy, query-validation or availability reason for a nil unit flag."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit für ein nil-Einheiten-Flag."
-- en: "Policy, query-validation or availability reason for nil attackability."
L["Policy, query-validation or availability reason for nil attackability."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit für eine nil-Angreifbarkeit."
-- en: "Policy, query-validation or identity/selector availability reason for a nil selector."
L["Policy, query-validation or identity/selector availability reason for a nil selector."] = "Grund aus Richtlinie, Abfragevalidierung oder Identitäts-/Selektorverfügbarkeit für einen nil-Selektor."
-- en: "Policy, query-validation or required observation availability reason for a nil quantity."
L["Policy, query-validation or required observation availability reason for a nil quantity."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit einer erforderlichen Beobachtung für eine nil-Menge."
-- en: "Policy, query-validation or required observation availability reason for a nil record."
L["Policy, query-validation or required observation availability reason for a nil record."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit einer erforderlichen Beobachtung für einen nil-Datensatz."
-- en: "Policy, query-validation or required-observation availability reason for a nil ID."
L["Policy, query-validation or required-observation availability reason for a nil ID."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit einer erforderlichen Beobachtung für eine nil-ID."
-- en: "Policy, query-validation or required-observation availability reason for a nil match."
L["Policy, query-validation or required-observation availability reason for a nil match."] = "Grund aus Richtlinie, Abfragevalidierung oder Verfügbarkeit einer erforderlichen Beobachtung für einen nil-Treffer."
-- en: "Policy, slot-validation or required observation availability reason for a nil type."
L["Policy, slot-validation or required observation availability reason for a nil type."] = "Grund aus Richtlinie, Platzvalidierung oder Verfügbarkeit einer erforderlichen Beobachtung für einen nil-Typ."
-- en: "Policy, slot-validation, capability or native-call availability reason for a nil record."
L["Policy, slot-validation, capability or native-call availability reason for a nil record."] = "Verfügbarkeitsgrund aus Richtlinie, Platzvalidierung, Client-Unterstützung oder nativem Aufruf für einen nil-Datensatz."
-- en: "Policy, snapshot, identity or threat observation availability reason."
L["Policy, snapshot, identity or threat observation availability reason."] = "Verfügbarkeitsgrund aus Richtlinie, Momentaufnahme, Identitäts- oder Bedrohungsbeobachtung."
-- en: "Policy, token-validation or availability reason for a nil identity result."
L["Policy, token-validation or availability reason for a nil identity result."] = "Grund aus Richtlinie, Kennungsvalidierung oder Verfügbarkeit für ein nil-Identitätsergebnis."
-- en: "Policy, validation or availability reason for a nil health observation."
L["Policy, validation or availability reason for a nil health observation."] = "Grund aus Richtlinie, Validierung oder Verfügbarkeit für eine nil-Gesundheitsbeobachtung."
-- en: "Policy, validation or availability reason for a nil snapshot."
L["Policy, validation or availability reason for a nil snapshot."] = "Grund aus Richtlinie, Validierung oder Verfügbarkeit für eine nil-Momentaufnahme."
-- en: "Policy, validation or observation availability reason."
L["Policy, validation or observation availability reason."] = "Grund aus Richtlinie, Validierung oder Beobachtungsverfügbarkeit."
-- en: "Policy, validation or required observation availability reason."
L["Policy, validation or required observation availability reason."] = "Grund aus Richtlinie, Validierung oder Verfügbarkeit einer erforderlichen Beobachtung."
-- en: "Positive integer glyph item ID stored by the condition; arrays, item-set keys and spell IDs are not item references."
L["Positive integer glyph item ID stored by the condition; arrays, item-set keys and spell IDs are not item references."] = "Positive ganzzahlige Gegenstands-ID der Glyphe, von der Bedingung gespeichert; Arrays, Gegenstandsset-Schlüssel und Zauber-IDs sind keine Gegenstandsreferenzen."
-- en: "Positive integer level, false for a known absent unit, or nil when unavailable."
L["Positive integer level, false for a known absent unit, or nil when unavailable."] = "Positive ganzzahlige Stufe, false für eine bekannt abwesende Einheit oder nil, wenn nicht verfügbar."
-- en: "Positive integer spell ID, not a spell-book slot."
L["Positive integer spell ID, not a spell-book slot."] = "Positive ganzzahlige Zauber-ID, kein Platz im Zauberbuch."
-- en: "Positive item ID or native-recognized item name/link to classify."
L["Positive item ID or native-recognized item name/link to classify."] = "Positive Gegenstands-ID oder nativ erkannter Gegenstandsname/-link zum Klassifizieren."
-- en: "Predicate that validates the proposed spell value."
L["Predicate that validates the proposed spell value."] = "Prädikat, das den vorgeschlagenen Zauberwert validiert."
-- en: "Present GUID, false for known absence, or nil when unavailable."
L["Present GUID, false for known absence, or nil when unavailable."] = "Vorhandene GUID, false bei bekannter Abwesenheit oder nil, wenn nicht verfügbar."
-- en: "Provider, validation or observation availability reason."
L["Provider, validation or observation availability reason."] = "Verfügbarkeitsgrund aus Anbieter, Validierung oder Beobachtung."
-- en: "Query, policy or observation availability reason."
L["Query, policy or observation availability reason."] = "Verfügbarkeitsgrund aus Abfrage, Richtlinie oder Beobachtung."
-- en: "RM comparison operator identifier; missing labels use the operator placeholder."
L["RM comparison operator identifier; missing labels use the operator placeholder."] = "RM-Vergleichsoperatorkennung; fehlende Beschriftungen verwenden den Operator-Platzhalter."
-- en: "RM operator identifier."
L["RM operator identifier."] = "RM-Operatorkennung."
-- en: "Range record with applicable and, when applicable, inRange; nil when unavailable."
L["Range record with applicable and, when applicable, inRange; nil when unavailable."] = "Reichweiten-Datensatz mit applicable und, falls zutreffend, inRange; nil, wenn nicht verfügbar."
-- en: "Read a fresh protected UnitClass player observation for rotation ownership. Consume only the readable nonempty class filename from return two. No existence, level, vehicle, family or combat-policy read is added, and no result persists across calls. Core ownership still validates the class token and character key separately; overridden context providers retain their complete original path."
L["Read a fresh protected UnitClass player observation for rotation ownership. Consume only the readable nonempty class filename from return two. No existence, level, vehicle, family or combat-policy read is added, and no result persists across calls. Core ownership still validates the class token and character key separately; overridden context providers retain their complete original path."] = "Eine frische geschützte UnitClass-Beobachtung von player für die Rotationszuordnung lesen. Verwendet wird nur der lesbare nichtleere Klassen-Dateiname aus Rückgabewert zwei. Es wird kein Lesen von Existenz, Stufe, Fahrzeug, Familie oder Kampfrichtlinie hinzugefügt, und kein Ergebnis bleibt über Aufrufe hinweg erhalten. Die Kernzuordnung validiert Klassenkennung und Charakterschlüssel weiterhin separat; überschriebene Kontextanbieter behalten ihren vollständigen ursprünglichen Pfad."
-- en: "Read a fresh protected zero-argument GetTime for rune cooldown arithmetic. Require a readable finite number. This observation is deliberately uncached; callers preserve the original clock-before-scan order and require its value only when a matching rune needs timing. No evaluation-start substitution or inferred time is supplied."
L["Read a fresh protected zero-argument GetTime for rune cooldown arithmetic. Require a readable finite number. This observation is deliberately uncached; callers preserve the original clock-before-scan order and require its value only when a matching rune needs timing. No evaluation-start substitution or inferred time is supplied."] = "Ein frisches geschütztes GetTime ohne Argumente für die Abklingzeit-Arithmetik der Runen lesen. Erforderlich ist eine lesbare endliche Zahl. Diese Beobachtung wird bewusst nicht zwischengespeichert; Aufrufer behalten die ursprüngliche Reihenfolge „Uhr vor Scan“ bei und benötigen den Wert nur, wenn eine passende Rune ein Timing braucht. Es wird weder der Auswertungsstart als Ersatz noch eine abgeleitete Zeit geliefert."
-- en: "Read a lazy health scalar after a separate identity gate. Kind current uses exact UnitHealth(unit); maximum uses exact UnitHealthMax(unit). Probe- and restricted-policy clients accept readable finite nonnegative numbers including zero. No repeated existence/GUID call or alternate tuple fallback is added."
L["Read a lazy health scalar after a separate identity gate. Kind current uses exact UnitHealth(unit); maximum uses exact UnitHealthMax(unit). Probe- and restricted-policy clients accept readable finite nonnegative numbers including zero. No repeated existence/GUID call or alternate tuple fallback is added."] = "Nach einer separaten Identitätsprüfung einen verzögerten Gesundheitsskalar lesen. Art current verwendet exakt UnitHealth(unit); maximum verwendet exakt UnitHealthMax(unit). Clients mit Probe- oder Restricted-Richtlinie akzeptieren lesbare endliche nichtnegative Zahlen einschließlich null. Es wird kein wiederholter Existenz-/GUID-Aufruf und kein alternativer Tupel-Rückgriff hinzugefügt."
-- en: "Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data return nil with a reason."
L["Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data return nil with a reason."] = "Einen normalisierten Aufladungs-Datensatz lesen: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate und isActive. Nicht unterstützte Zauber oder eingeschränkte Clientdaten ergeben nil mit einem Grund."
-- en: "Read a specified unit membership in the player party or raid. True raidOnly queries only UnitInRaid; otherwise a true UnitInParty result short-circuits, false proceeds to UnitInRaid, and unknown remains unavailable. Readable nil raid index means false; integer raid index1..40 means true. Names are passed unchanged to native APIs; native name-query acceptance requires client qualification."
L["Read a specified unit membership in the player party or raid. True raidOnly queries only UnitInRaid; otherwise a true UnitInParty result short-circuits, false proceeds to UnitInRaid, and unknown remains unavailable. Readable nil raid index means false; integer raid index1..40 means true. Names are passed unchanged to native APIs; native name-query acceptance requires client qualification."] = "Die Zugehörigkeit einer angegebenen Einheit zur Gruppe oder zum Schlachtzug des Spielers lesen. raidOnly true fragt nur UnitInRaid ab; andernfalls beendet ein Ergebnis true von UnitInParty die Prüfung sofort, false geht weiter zu UnitInRaid, und unbekannt bleibt nicht verfügbar. Ein lesbarer nil-Schlachtzugsindex bedeutet false; ein ganzzahliger Schlachtzugsindex 1..40 bedeutet true. Namen werden unverändert an native APIs übergeben; ob native Namensabfragen akzeptiert werden, muss je Client bestätigt werden."
-- en: "Read and normalize a spell cooldown across supported clients. The returned record contains startTime, duration, isEnabled and modRate. The timestamps and duration already describe expiration in GetTime() seconds; do not divide them by modRate. When the client hides the times (Retail and Forever in combat) the record is nil with reason restricted-value, followed by the never-secret isEnabled, isActive and isOnGCD flags when they can be read."
L["Read and normalize a spell cooldown across supported clients. The returned record contains startTime, duration, isEnabled and modRate. The timestamps and duration already describe expiration in GetTime() seconds; do not divide them by modRate. When the client hides the times (Retail and Forever in combat) the record is nil with reason restricted-value, followed by the never-secret isEnabled, isActive and isOnGCD flags when they can be read."] = "Liest die Abklingzeit eines Zaubers und normalisiert sie über alle unterstützten Clients. Der zurückgegebene Datensatz enthält startTime, duration, isEnabled und modRate. Die Zeitstempel und duration beschreiben den Ablauf bereits in GetTime()-Sekunden; teilen Sie sie nicht durch modRate. Wenn der Client die Zeiten verbirgt (Retail und Forever im Kampf), ist der Datensatz nil mit dem Grund restricted-value, gefolgt von den nie geheimen Flags isEnabled, isActive und isOnGCD, sofern sie gelesen werden können."
-- en: "Read normalized native item classification metadata. The record contains canonical itemID, classID and subClassID, plus equipLoc, the non-localized INVTYPE_* equip location token, when it is readable and nonempty; it does not require loaded item display text. Missing, failed, malformed or restricted metadata returns nil with a reason."
L["Read normalized native item classification metadata. The record contains canonical itemID, classID and subClassID, plus equipLoc, the non-localized INVTYPE_* equip location token, when it is readable and nonempty; it does not require loaded item display text. Missing, failed, malformed or restricted metadata returns nil with a reason."] = "Normalisierte native Klassifizierungsmetadaten eines Gegenstands lesen. Der Datensatz enthält die kanonischen itemID, classID und subClassID sowie equipLoc, das nicht lokalisierte INVTYPE_*-Token der Ausrüstungsposition, wenn es lesbar und nicht leer ist; geladener Anzeigetext des Gegenstands ist nicht erforderlich. Fehlende, fehlgeschlagene, fehlerhafte oder eingeschränkte Metadaten ergeben nil mit einem Grund."
-- en: "Read one documented active loss-of-control row by its native index and requested subject kind. Type queries require only the readable control type string; school queries require only the readable finite nonnegative integer school mask. Optional timing is returned as a finite timeRemaining or an explicit per-field reason, so an unrelated subject does not require a usable timer. Missing rows are unavailable snapshot observations. No display fields, inferred deadline, duration sum, maximum or native alias fallback is used."
L["Read one documented active loss-of-control row by its native index and requested subject kind. Type queries require only the readable control type string; school queries require only the readable finite nonnegative integer school mask. Optional timing is returned as a finite timeRemaining or an explicit per-field reason, so an unrelated subject does not require a usable timer. Missing rows are unavailable snapshot observations. No display fields, inferred deadline, duration sum, maximum or native alias fallback is used."] = "Eine dokumentierte aktive Kontrollverlust-Zeile über ihren nativen Index und die angefragte Subjektart lesen. Typabfragen benötigen nur die lesbare Zeichenkette des Kontrolltyps; Schulabfragen nur die lesbare endliche nichtnegative ganzzahlige Zauberschulmaske. Optionales Timing wird als endliches timeRemaining oder als expliziter Grund pro Feld zurückgegeben, sodass ein nicht betroffenes Subjekt keinen nutzbaren Timer benötigt. Fehlende Zeilen sind nicht verfügbare Beobachtungen der Momentaufnahme. Es werden keine Anzeigefelder, abgeleiteten Fristen, Dauersummen, Maxima oder nativen Alias-Rückgriffe verwendet."
-- en: "Read one explicitly selected point-resource quantity with an exact two-argument UnitPower or UnitPowerMax query. The selector is required; no primary-resource inference or actor remapping occurs. Preserve finite signed, fractional and zero quantities without clamping. Missing, failed, restricted or nonfinite data remains unavailable. Current and maximum are separate observations so callers can share current snapshots while requesting maximum lazily."
L["Read one explicitly selected point-resource quantity with an exact two-argument UnitPower or UnitPowerMax query. The selector is required; no primary-resource inference or actor remapping occurs. Preserve finite signed, fractional and zero quantities without clamping. Missing, failed, restricted or nonfinite data remains unavailable. Current and maximum are separate observations so callers can share current snapshots while requesting maximum lazily."] = "Eine explizit ausgewählte Punktressourcenmenge mit einer exakten UnitPower- oder UnitPowerMax-Abfrage mit zwei Argumenten lesen. Der Selektor ist erforderlich; es erfolgt weder eine Ableitung der Primärressource noch eine Umleitung des Akteurs. Endliche vorzeichenbehaftete, gebrochene und Nullmengen bleiben ohne Begrenzung erhalten. Fehlende, fehlgeschlagene, eingeschränkte oder nicht endliche Daten bleiben nicht verfügbar. Aktuell und Maximum sind getrennte Beobachtungen, damit Aufrufer aktuelle Momentaufnahmen teilen und das Maximum bei Bedarf verzögert anfragen können."
-- en: "Read one protected GetRuneCooldown tuple for an exact native slot. Normalize ready, start and duration independently: ready requires a readable Boolean, while each time requires a readable finite number and preserves signed, fractional and zero values. Every unavailable field carries its own reason. A successful empty tuple yields a partial record; missing capability, policy or native-call failure yields nil. Never infer ready from timing or timing from ready. Cache this complete record at the caller to share one observation between rune-count and cooldown predicates."
L["Read one protected GetRuneCooldown tuple for an exact native slot. Normalize ready, start and duration independently: ready requires a readable Boolean, while each time requires a readable finite number and preserves signed, fractional and zero values. Every unavailable field carries its own reason. A successful empty tuple yields a partial record; missing capability, policy or native-call failure yields nil. Never infer ready from timing or timing from ready. Cache this complete record at the caller to share one observation between rune-count and cooldown predicates."] = "Ein geschütztes GetRuneCooldown-Tupel für einen exakten nativen Platz lesen. ready, start und duration unabhängig normalisieren: ready erfordert einen lesbaren booleschen Wert, jede Zeit eine lesbare endliche Zahl, wobei vorzeichenbehaftete, gebrochene und Nullwerte erhalten bleiben. Jedes nicht verfügbare Feld trägt seinen eigenen Grund. Ein erfolgreiches leeres Tupel ergibt einen teilweisen Datensatz; fehlende Client-Unterstützung, Richtlinie oder ein Fehlschlag des nativen Aufrufs ergibt nil. Nie ready aus dem Timing oder das Timing aus ready ableiten. Diesen vollständigen Datensatz beim Aufrufer zwischenspeichern, um eine Beobachtung zwischen Prädikaten für Runenanzahl und Abklingzeit zu teilen."
-- en: "Read optional MobInfo2 historical observations on probe- and restricted-policy clients. Cache only exact selected-unit presence; UnitName result one, UnitLevel result one and the three-argument MI2_GetMobData(name,level,unit) dot call stay fresh each invocation. Known absent units and successful unrecorded nil or omitted history remain distinct from unavailable native/provider facts. Preserve readable runner scalar truthiness, school signs and missing-Hits default one. Positive resistance ratios must be finite; complete immunity consumes finite Hits while partial immunity needs only its negative school observation. Never infer native resistance or borrow old records."
L["Read optional MobInfo2 historical observations on probe- and restricted-policy clients. Cache only exact selected-unit presence; UnitName result one, UnitLevel result one and the three-argument MI2_GetMobData(name,level,unit) dot call stay fresh each invocation. Known absent units and successful unrecorded nil or omitted history remain distinct from unavailable native/provider facts. Preserve readable runner scalar truthiness, school signs and missing-Hits default one. Positive resistance ratios must be finite; complete immunity consumes finite Hits while partial immunity needs only its negative school observation. Never infer native resistance or borrow old records."] = "Optionale historische Beobachtungen von MobInfo2 auf Clients mit Probe- oder Restricted-Richtlinie lesen. Nur die exakte Anwesenheit der ausgewählten Einheit wird zwischengespeichert; Ergebnis eins von UnitName, Ergebnis eins von UnitLevel und der Punktaufruf MI2_GetMobData(name,level,unit) mit drei Argumenten bleiben bei jedem Aufruf frisch. Bekannt abwesende Einheiten und erfolgreich nicht aufgezeichnete nil- oder fehlende Verläufe bleiben von nicht verfügbaren nativen Fakten und Anbieterfakten unterscheidbar. Lesbarer Wahrheitswert des runner-Skalars, Schulvorzeichen und der Standardwert eins bei fehlendem Hits bleiben erhalten. Positive Widerstandsquoten müssen endlich sein; vollständige Immunität verwendet endliche Hits, teilweise Immunität benötigt nur ihre negative Schulbeobachtung. Nie nativen Widerstand ableiten oder alte Datensätze übernehmen."
-- en: "Read optional RealMobHealth using its exact one-argument dot call. Absent nil/false namespace returns an empty record. Normalize current and maximum independently: nil/false fields permit native fallback, numeric zero remains present. Malformed, failed, restricted, negative or nonfinite consumed provider facts are unavailable. No provider or stale fallback cache is used."
L["Read optional RealMobHealth using its exact one-argument dot call. Absent nil/false namespace returns an empty record. Normalize current and maximum independently: nil/false fields permit native fallback, numeric zero remains present. Malformed, failed, restricted, negative or nonfinite consumed provider facts are unavailable. No provider or stale fallback cache is used."] = "Optionales RealMobHealth über seinen exakten Punktaufruf mit einem Argument lesen. Ein fehlender Namensraum (nil/false) ergibt einen leeren Datensatz. current und maximum unabhängig normalisieren: nil/false-Felder erlauben den nativen Rückgriff, numerische Null bleibt vorhanden. Fehlerhafte, fehlgeschlagene, eingeschränkte, negative oder nicht endliche verwendete Anbieterfakten sind nicht verfügbar. Es wird kein Anbieter- oder veralteter Rückgriff-Cache verwendet."
-- en: "Read public group membership on identified client families. Unknown clients are unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native default group category. A readable false result stays false. Missing, failed, malformed or restricted observations return nil with a reason."
L["Read public group membership on identified client families. Unknown clients are unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native default group category. A readable false result stays false. Missing, failed, malformed or restricted observations return nil with a reason."] = "Öffentliche Gruppenzugehörigkeit auf identifizierten Client-Familien lesen. Unbekannte Clients werden nicht unterstützt. raidOnly true prüft IsInRaid; false oder nil prüft IsInGroup mit dessen nativer Standard-Gruppenkategorie. Ein lesbares Ergebnis false bleibt false. Fehlende, fehlgeschlagene, fehlerhafte oder eingeschränkte Beobachtungen ergeben nil mit einem Grund."
-- en: "Read public roster identity on identified client families. Input routing is limited to player, party1 through party4 and raid1 through raid40. Call UnitExists with that exact one-argument token first; known false returns false without querying class. For a present unit, consume only UnitClass return two as a readable nonempty class filename string, without a class enum restriction. Missing, failed, malformed or restricted required facts return nil with a reason."
L["Read public roster identity on identified client families. Input routing is limited to player, party1 through party4 and raid1 through raid40. Call UnitExists with that exact one-argument token first; known false returns false without querying class. For a present unit, consume only UnitClass return two as a readable nonempty class filename string, without a class enum restriction. Missing, failed, malformed or restricted required facts return nil with a reason."] = "Öffentliche Identität der Gruppenmitglieder auf identifizierten Client-Familien lesen. Eingaben sind auf player, party1 bis party4 und raid1 bis raid40 beschränkt. Zuerst UnitExists mit genau dieser Kennung als einzigem Argument aufrufen; bekanntes false ergibt false, ohne die Klasse abzufragen. Für eine vorhandene Einheit nur Rückgabewert zwei von UnitClass als lesbare nichtleere Klassen-Dateinamen-Zeichenkette verwenden, ohne Beschränkung auf ein Klassen-Enum. Fehlende, fehlgeschlagene, fehlerhafte oder eingeschränkte erforderliche Fakten ergeben nil mit einem Grund."
-- en: "Read spell-specific range for a unit using the appropriate client API or spell-book slot. A spell without a range restriction returns applicable=false; otherwise applicable=true and inRange records whether the unit is in range. Unknown or inaccessible observations return nil with a reason."
L["Read spell-specific range for a unit using the appropriate client API or spell-book slot. A spell without a range restriction returns applicable=false; otherwise applicable=true and inRange records whether the unit is in range. Unknown or inaccessible observations return nil with a reason."] = "Die zauberspezifische Reichweite für eine Einheit über die passende Client-API oder den Platz im Zauberbuch lesen. Ein Zauber ohne Reichweitenbeschränkung ergibt applicable=false; andernfalls applicable=true, und inRange gibt an, ob die Einheit in Reichweite ist. Unbekannte oder unzugängliche Beobachtungen ergeben nil mit einem Grund."
-- en: "Read the current positive nameplate visibility distance using the supported CVar API. This limits a Distance Count query; it does not prove that all nearby units have been observed. Missing, malformed, restricted or failed observations return nil with a reason."
L["Read the current positive nameplate visibility distance using the supported CVar API. This limits a Distance Count query; it does not prove that all nearby units have been observed. Missing, malformed, restricted or failed observations return nil with a reason."] = "Die aktuelle positive Sichtweite der Namensplaketten über die unterstützte CVar-API lesen. Dies begrenzt eine Abfrage für „Anzahl in Entfernung“; es belegt nicht, dass alle Einheiten in der Nähe beobachtet wurden. Fehlende, fehlerhafte, eingeschränkte oder fehlgeschlagene Beobachtungen ergeben nil mit einem Grund."
-- en: "Read the documented active loss-of-control count with a protected zero-argument dot call. Require a readable finite nonnegative integer. Zero is a complete empty scan and does not require a row API. RM limits a scan to 256 rows and returns unavailable beyond that resource budget; this is not a declared native maximum. Required missing, failed, restricted or malformed observations remain unavailable."
L["Read the documented active loss-of-control count with a protected zero-argument dot call. Require a readable finite nonnegative integer. Zero is a complete empty scan and does not require a row API. RM limits a scan to 256 rows and returns unavailable beyond that resource budget; this is not a declared native maximum. Required missing, failed, restricted or malformed observations remain unavailable."] = "Die dokumentierte Anzahl aktiver Kontrollverluste mit einem geschützten Punktaufruf ohne Argumente lesen. Erforderlich ist eine lesbare endliche nichtnegative ganze Zahl. Null ist ein vollständiger leerer Scan und benötigt keine Zeilen-API. RM begrenzt einen Scan auf 256 Zeilen und gibt jenseits dieses Ressourcenbudgets „nicht verfügbar“ zurück; dies ist kein deklariertes natives Maximum. Erforderliche fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen bleiben nicht verfügbar."
-- en: "Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This is distinct from a current or queued cast. Modern clients receive the exact spell ID; a legacy query resolves the player spell-book slot first. Restricted client policies, unreadable results and unavailable book slots return nil with a reason. This observes state and never starts or stops a spell."
L["Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This is distinct from a current or queued cast. Modern clients receive the exact spell ID; a legacy query resolves the player spell-book slot first. Restricted client policies, unreadable results and unavailable book slots return nil with a reason. This observes state and never starts or stops a spell."] = "Den Status der automatischen Wiederholung des Spielers für einen Zauber wie Schießen oder Automatischer Schuss lesen. Dies unterscheidet sich von einem aktuellen oder eingereihten Zauber. Moderne Clients erhalten die exakte Zauber-ID; eine alte Abfrage löst zuerst den Platz im Zauberbuch des Spielers auf. Eingeschränkte Client-Richtlinien, unlesbare Ergebnisse und nicht verfügbare Zauberbuchplätze ergeben nil mit einem Grund. Dies beobachtet nur den Zustand und startet oder stoppt nie einen Zauber."
-- en: "Read the public LibRangeCheck interval for a unit. A successful upper bound is inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither bound is an exact distance, and a missing upper bound is not proof that the unit is outside every radius. Unavailable, malformed, restricted or failed observations return nil with a reason."
L["Read the public LibRangeCheck interval for a unit. A successful upper bound is inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither bound is an exact distance, and a missing upper bound is not proof that the unit is outside every radius. Unavailable, malformed, restricted or failed observations return nil with a reason."] = "Das öffentliche LibRangeCheck-Intervall für eine Einheit lesen. Eine erfolgreiche Obergrenze ist inklusiv; eine positive fehlgeschlagene Untergrenze ist strikt. Eine Untergrenze von null ist synthetisch. Keine der Grenzen ist eine exakte Entfernung, und eine fehlende Obergrenze belegt nicht, dass die Einheit außerhalb jedes Radius liegt. Nicht verfügbare, fehlerhafte, eingeschränkte oder fehlgeschlagene Beobachtungen ergeben nil mit einem Grund."
-- en: "Readability authority for consumed values."
L["Readability authority for consumed values."] = "Maßgebliche Lesbarkeitsprüfung für verwendete Werte."
-- en: "Readable canonical item classification record (itemID, classID, subClassID and optional equipLoc), or nil when unavailable."
L["Readable canonical item classification record (itemID, classID, subClassID and optional equipLoc), or nil when unavailable."] = "Lesbarer kanonischer Datensatz zur Gegenstandsklassifizierung (itemID, classID, subClassID und optional equipLoc) oder nil, wenn nicht verfügbar."
-- en: "Readable canonical itemID/classID/subClassID record when the item is a glyph for the requested class; nil for invalid or unavailable metadata."
L["Readable canonical itemID/classID/subClassID record when the item is a glyph for the requested class; nil for invalid or unavailable metadata."] = "Lesbarer kanonischer itemID/classID/subClassID-Datensatz, wenn der Gegenstand eine Glyphe für die angefragte Klasse ist; nil bei ungültigen oder nicht verfügbaren Metadaten."
-- en: "Readable charge record, or nil when unavailable."
L["Readable charge record, or nil when unavailable."] = "Lesbarer Aufladungs-Datensatz oder nil, wenn nicht verfügbar."
-- en: "Readable consumed metadata string, false for a known absent unit, or nil when required data is unavailable."
L["Readable consumed metadata string, false for a known absent unit, or nil when required data is unavailable."] = "Lesbare verwendete Metadaten-Zeichenkette, false für eine bekannt abwesende Einheit oder nil, wenn erforderliche Daten nicht verfügbar sind."
-- en: "Readable cooldown record, or nil when unavailable."
L["Readable cooldown record, or nil when unavailable."] = "Lesbarer Abklingzeit-Datensatz oder nil, wenn nicht verfügbar."
-- en: "Readable current state, or nil when unavailable."
L["Readable current state, or nil when unavailable."] = "Lesbarer aktueller Zustand oder nil, wenn nicht verfügbar."
-- en: "Readable finite current-form observation, including zero for the current unshifted comparison; nil when unavailable."
L["Readable finite current-form observation, including zero for the current unshifted comparison; nil when unavailable."] = "Lesbare endliche Beobachtung der aktuellen Gestalt, einschließlich null für den Vergleich ohne Gestaltwandlung; nil, wenn nicht verfügbar."
-- en: "Readable finite positive integral rune type, or nil when unavailable."
L["Readable finite positive integral rune type, or nil when unavailable."] = "Lesbarer endlicher positiver ganzzahliger Runentyp oder nil, wenn nicht verfügbar."
-- en: "Readable interval with optional minimum and maximum bounds in yards. At least one bound is present; nil when unavailable."
